    mov [ebp + hTextID], al
    call DisplayTextID
    xor al, al
    mov [ebp + hJoyHeld], al
    mov [ebp + hJoyPressed], al
    ret

%assign event_byte -1
%assign event_byte_a -1
PokemonTower2FRivalEncounterEventCoords:
